<?php $document=in_array($_GET['document']??'',['privacy','terms','cookies'],true)?$_GET['document']:'privacy';$operator=Zion\LegalDocuments::operator();$text=Zion\LegalDocuments::read($locale,$document); ?>
<section class="wrap legal-page"><header class="legal-heading"><p class="eyebrow">ZION STORAGE</p><h1><?= e($t('legal.'.$document)) ?></h1><p><?= e($t('legal.updated')) ?> <?= Zion\LegalDocuments::VERSION ?></p><nav class="legal-nav" aria-label="<?= e($t('legal.title')) ?>"><?php foreach(['privacy','terms','cookies'] as $doc): ?><a href="<?= $url('legal') ?>?document=<?= $doc ?>" <?= $doc===$document?'aria-current="page"':'' ?>><?= e($t('legal.'.$doc)) ?></a><?php endforeach ?></nav></header>
<aside class="legal-operator"><strong><?= e($operator['name']) ?></strong><p>CUI <?= e($operator['tax_id']) ?> · <?= e($operator['registration']) ?><br><?= e($operator['address']) ?><br><a href="mailto:<?= e($operator['email']) ?>"><?= e($operator['email']) ?></a> · <a href="tel:+40770675597"><?= e($operator['phone']) ?></a></p></aside>
<article class="legal-content"><?php if($text): foreach(preg_split('/\n\s*\n/u',trim($text)) as $section): $lines=explode("\n",$section); ?><section><?php if(preg_match('/^\d+\. /u',$lines[0])): ?><h2><?= e(array_shift($lines)) ?></h2><?php endif ?><p><?= nl2br(e(implode("\n",$lines))) ?></p></section><?php endforeach;else: ?><p><?= e($t('legal.pending')) ?></p><?php endif ?></article>
<?php if($document==='terms'): ?><a class="button outline" href="<?= $url('contact') ?>?request=withdrawal"><?= e($t('withdrawal.title')) ?></a><?php endif ?>
</section>
